fn reverse_odd(s: &str) -> String {
    let mut chars: Vec<char> = s.chars().collect();
    let odd_chars: Vec<char> = chars.iter().enumerate()
        .filter(|(i, _)| i % 2 != 0)
        .map(|(_, c)| *c)
        .collect();
    let mut reversed_odd_chars = odd_chars.iter().rev().cloned().collect::<Vec<char>>();
    let mut j = 0;
    for i in 0..chars.len() {
        if i % 2 != 0 {
            chars[i] = reversed_odd_chars[j];
            j += 1;
        }
    }
    chars.into_iter().collect()
}
```

