```javascript
function multiply(lst1, lst2) {
    // Initialize variables to hold products and sums
    let product1 = 1, product2 = 1, sum1 = 0, sum2 = 0;

    // Iterate through lst1
    for (let i = 0; i < lst1.length; i++) {
        // Check if index is even and element is odd
        if (i % 2 === 0 && lst1[i] % 2 !== 0) {
            product1 *= lst1[i];
        }
        // Check if element is even for adding to sum
        if (lst1[i] % 2 === 0) {
            sum1 += lst1[i];
        }
    }

    // Iterate through lst2
    for (let i = 0; i < lst2.length; i++) {
        // Check if index is odd and element is even
        if (i % 2 !== 0 && lst2[i] % 2 === 0) {
            product2 *= lst2[i];
        }
        // Check if element is odd for adding to sum
        if (lst2[i] % 2 !== 0) {
            sum2 += lst2[i];
        }
    }

    // Return the two product and two sum values
    return [product1, product2, sum1, sum2];
}
```

